const SCHEMA='foko.research/1',params=new URLSearchParams(location.search),keys={last:'foko:research:last',recent:'foko:research:recent'},S={id:'research-'+Date.now().toString(36),model:null,data:null,path:null,records:[],current:{},notes:{hypothesis:'',interpretation:'',nextTest:''},revision:0,sequence:0,job:null,invalid:null,draftDirty:false,dataDraftDirty:false,tab:'model',pin:null,pendingModel:null,scenarios:[],attachments:[]};let saveTimer,liveTimer;
