 document.querySelectorAll('[data-param],[data-initial],[data-slider]').forEach(input=>input.addEventListener('input',()=>{if(input.dataset.param){document.querySelectorAll('[data-param]').forEach(other=>{if(other!==input&&other.dataset.param===input.dataset.param&&other.dataset.paramPart===input.dataset.paramPart)other.value=input.value;});if(input.dataset.paramPart==='0')document.querySelectorAll('[data-slider]').forEach(s=>{if(s.dataset.slider===input.dataset.param)s.value=input.value;});}else if(input.dataset.slider){document.querySelectorAll('[data-param]').forEach(other=>{if(other.dataset.param===input.dataset.slider&&other.dataset.paramPart==='0')other.value=input.value;});}editBasic();}));document.querySelectorAll('[data-fit-param],[data-ensemble-param]').forEach(x=>x.onchange=()=>invalidate('Analysis selection changed. Run again; earlier results remain in Evidence.'));
