function renderMetadata(){const m=S.model;$('workspaceTitle').textContent=m.name;$('workspaceDomain').textContent=S.path?.domain||'Your model · connected experiment';$('workspaceQuestion').textContent=m.question||'Write the scientific question before interpreting a calculation.';$('pathContext').textContent=S.path?.context||m.description||'Record the system, observation process and scope of use.';$('pathLesson').href='learn.html?lesson='+(S.path?.lesson||'question');$('modelScope').innerHTML=`<p>${esc(S.path?.source||'User-authored model; provenance and empirical validity are not established by this application.')}</p><ul style="padding-left:20px;margin-top:14px;font-size:13px;color:var(--muted)">${m.assumptions.map(a=>`<li style="margin:7px 0">${esc(a)}</li>`).join('')||'<li>No assumptions recorded yet.</li>'}</ul>${S.path?`<p><b>Try this:</b> ${esc(S.path.exercise)}</p><p><b>Boundary:</b> ${esc(S.path.risk)}</p><p><a href="${esc(S.path.research)}">Source research and deeper methods →</a></p>`:''}`;$('equations').innerHTML=m.vars.map((v,i)=>`<div class="equation"><b>d${esc(v)}/dt</b> = ${esc(m.eqs[i])}</div>`).join('')+(m.observables?.length?'<h4 class="form-heading">Declared measurements</h4>'+m.observables.map(o=>`<div class="equation"><b>${esc(o.id)}</b> = ${esc(o.expression)} <small> [${esc(o.unit)}]</small></div>`).join(''):'');}
